SELECT id, workspace_id, session_id, seq, author_kind, author_user_id, content,
       structured_json, input_tokens, output_tokens, created_at
FROM ai_chat_message
WHERE workspace_id = #{workspaceId}
  AND session_id = #{sessionId}
ORDER BY seq ASC
LIMIT #{limit} OFFSET #{offset}

SELECT recent.id, recent.workspace_id, recent.session_id, recent.seq,
       recent.author_kind, recent.author_user_id, recent.content,
       recent.structured_json, recent.input_tokens, recent.output_tokens,
       recent.created_at
FROM (
  SELECT id, workspace_id, session_id, seq, author_kind, author_user_id, content,
         structured_json, input_tokens, output_tokens, created_at
  FROM ai_chat_message
  WHERE workspace_id = #{workspaceId}
    AND session_id = #{sessionId}
    AND seq <= #{maxSeq}
  ORDER BY seq DESC
  LIMIT #{limit}
) recent
ORDER BY recent.seq ASC

